  [440531] = {
    [1] = {
      beijing = 0,
      dialog = 6,
      hide_magnifier = 1,
      music = "57_Tanabata",
      renwu = "npc",
      sentence = [[
Heaven above, earth below, six points of the compass, wherein reside the gods, strange but human-like.

Of these, from the bottomless pit to the highest peak, exploring all the ends of the earth, upholding its laws, keeping watch on the horizon.

The stars revolved and the wheel of history turned, a trespasser stumbled on a rotten axe handle in the mountains, witnessed the blossoming of a peach tree, and legends were born.

A worshipper built a temple, made offerings, day and night praying for a miracle: "Bless my people, let the sun shine, let the rain fall, fill my belly at harvest time".

Inscriptions in the stone, blown away by the wind; who shall remember them?]],
      next = {2}
    },
    [2] = {
      beijing = 8120,
      dialog = 3,
      music = "PW_1_QuiteNight",
      renwu = "npc",
      sentence = "The legendary Qilin is a Lucky Beast that bestows upon its possessor the ability to dispel all misfortune.",
      next = {3}
    },
    [3] = {
      beijing = 8120,
      dhead = 112,
      dialog = 1,
      music = "PW_1_QuiteNight",
      renming = "$u",
      renwu = "npc",
      sentence = "Is there really such a thing as a Qilin?",
      next = {4}
    },
    [4] = {
      beijing = 8120,
      dialog = 3,
      music = "PW_1_QuiteNight",
      renwu = "npc",
      sentence = "The lofty mountains rose up before me. The journey had taken four days and four nights.",
      next = {5}
    },
    [5] = {
      beijing = 8120,
      dialog = 3,
      music = "PW_1_QuiteNight",
      renwu = "npc",
      sentence = "The Temple Elder had pointed to the map and said, \"Beyond this point the Qilin will appear.\"",
      next = {6}
    },
    [6] = {
      beijing = 8120,
      dhead = 106,
      dialog = 1,
      music = "PW_1_QuiteNight",
      renming = "$u",
      renwu = "npc",
      sentence = "God willing, I will find the Qilin soon.",
      next = {7}
    },
    [7] = {
      beijing = 8120,
      dhead = 106,
      dialog = 1,
      music = "PW_1_QuiteNight",
      renming = "$u",
      renwu = "npc",
      sentence = "If not...",
      next = {8}
    },
    [8] = {
      beijing = 8120,
      dialog = 3,
      music = "PW_1_QuiteNight",
      renwu = "npc",
      sentence = "I take a deep breath and start to climb the Holy Mountain.",
      next = {9}
    },
    [9] = {
      beijing = 8120,
      dialog = 3,
      music = "PW_1_QuiteNight",
      renwu = "npc",
      sentence = "The silence is absolute, as though I am the first person to ever come this way.",
      next = {10}
    },
    [10] = {
      beijing = 8120,
      dialog = 3,
      music = "PW_1_QuiteNight",
      renwu = "npc",
      sentence = "Only halfway up and I was already spent. Leaning against a tree, I rubbed my stomach which was aching with hunger.",
      next = {11}
    },
    [11] = {
      beijing = 8120,
      dhead = 105,
      dialog = 1,
      music = "PW_1_QuiteNight",
      renming = "$u",
      renwu = "npc",
      sentence = "Uh... All my rations are gone...",
      next = {12}
    },
    [12] = {
      beijing = 8120,
      dialog = 3,
      music = "PW_1_QuiteNight",
      renwu = "npc",
      sentence = "Looking up, I saw something shining in the distance. I pushed on, curious to find the source.",
      next = {13}
    },
    [13] = {
      beijing = 8120,
      dhead = 111,
      dialog = 1,
      music = "PW_1_QuiteNight",
      renming = "$u",
      renwu = "npc",
      sentence = "A lake!",
      next = {14}
    },
    [14] = {
      beijing = 8120,
      dialog = 3,
      music = "PW_1_QuiteNight",
      renwu = "npc",
      sentence = "Hundreds of red carp swam lazily in the crystal waters.",
      next = {15}
    },
    [15] = {
      beijing = 8120,
      dhead = 113,
      dialog = 1,
      music = "PW_1_QuiteNight",
      renming = "$u",
      renwu = "npc",
      sentence = "Yes! Now I can eat!",
      next = {16}
    },
    [16] = {
      beijing = 8110,
      bganim = 0,
      dialog = 3,
      music = "PW_1_QuiteNight",
      renwu = "npc",
      sentence = "Cautiously I lifted up my skirt and stepped into the water.",
      next = {17}
    },
    [17] = {
      beijing = 8110,
      dialog = 3,
      music = "PW_1_QuiteNight",
      renwu = "npc",
      sentence = "I'd tried catching fish by hand back at the village and had become quite good at it. Now was my chance to put it to use.",
      next = {18}
    },
    [18] = {
      beijing = 8110,
      dialog = 3,
      music = "PW_1_QuiteNight",
      renwu = "npc",
      sentence = "Dappled sunshine fell around me. I held my breath and pushed my way through the cold water, towards one particularly sleepy-looking fish.",
      next = {19}
    },
    [19] = {
